-- 只读；专属随机 schema，不得 public；原四表/capability 定义必须完全匹配，增量完全不存在。
SELECT current_schema() AS selected_schema,version() AS postgres_version;
SELECT table_name,ordinal_position,column_name,data_type,udt_schema,udt_name,character_maximum_length,numeric_precision,numeric_scale,datetime_precision,is_nullable,column_default,collation_name,is_identity,identity_generation,is_generated,generation_expression FROM information_schema.columns WHERE table_schema=current_schema() AND table_name IN ('agent_memory_thread_execution','agent_memory_thread_member','agent_memory_thread_namespace','agent_memory_thread_resume') ORDER BY table_name,ordinal_position;
SELECT c.relname,k.conname,k.contype,pg_get_constraintdef(k.oid) AS definition FROM pg_constraint k JOIN pg_class c ON c.oid=k.conrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname=current_schema() AND c.relname IN ('agent_memory_thread_execution','agent_memory_thread_member','agent_memory_thread_namespace','agent_memory_thread_resume') ORDER BY c.relname,k.conname;
SELECT tablename,indexname,indexdef FROM pg_indexes WHERE schemaname=current_schema() AND tablename IN ('agent_memory_thread_execution','agent_memory_thread_member','agent_memory_thread_namespace','agent_memory_thread_resume') ORDER BY tablename,indexname;
SELECT c.relname,t.tgname,pg_get_triggerdef(t.oid) AS definition,pg_get_functiondef(t.tgfoid) AS function_definition FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname=current_schema() AND c.relname IN ('agent_memory_thread_execution','agent_memory_thread_resume') AND NOT t.tgisinternal ORDER BY c.relname,t.tgname;
SELECT count(*) AS existing_delta_columns FROM information_schema.columns WHERE table_schema=current_schema() AND ((table_name='agent_memory_thread_execution' AND column_name IN ('current_context_fingerprint','wait_status','wait_packet_revision','wait_context_fingerprint','wait_phase','wait_checkpoint_ns','wait_checkpoint_id','pending_resume_request_id','pending_candidate_digest','pending_packet_revision','pending_context_fingerprint','terminal_reason')) OR (table_name='agent_memory_thread_resume' AND column_name IN ('record_kind','candidate_id','wait_event_id','operation_id','attempt','canonical_request_hmac','wait_phase','old_packet_revision','packet_revision','execution_revision','expected_current_context_fingerprint','target_context_fingerprint','candidate_digest','issued_at','expires_at','candidate_phase','current_packet_revision','current_context_fingerprint','refresh_count','receipt_state','next_wait_event_id','dispatch_allowed','authorization_binding')));
SELECT count(*) AS incompatible_receipts FROM agent_memory_thread_resume WHERE result_code IN ('CONTEXT_REFRESHED','MEMORY_REFRESH_PENDING','MEMORY_REFRESH_PACKET_EXPIRED') OR (result_code IN ('DELETE_PENDING','DELETED') AND (CASE WHEN pg_input_is_valid(resume_request_id,'jsonb') THEN CASE WHEN jsonb_typeof(resume_request_id::jsonb)='array' THEN (jsonb_array_length(resume_request_id::jsonb)=3 AND jsonb_typeof(resume_request_id::jsonb->0)='string' AND resume_request_id::jsonb->>0='memory-thread-receipt/2' AND jsonb_typeof(resume_request_id::jsonb->1)='string' AND resume_request_id::jsonb->>1='ERASURE' AND jsonb_typeof(resume_request_id::jsonb->2)='string' AND length(resume_request_id::jsonb->>2)>0 AND resume_request_id::jsonb->>2 !~ '^[[:space:]]*$') IS TRUE ELSE FALSE END ELSE FALSE END) IS NOT TRUE);
SELECT count(*) AS existing_delta_indexes FROM pg_indexes WHERE schemaname=current_schema() AND indexname IN ('uk_memory_thread_refresh_candidate','uk_memory_thread_refresh_pending');
SELECT count(*) AS existing_delta_functions FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname=current_schema() AND p.proname IN ('memory_thread_refresh_receipt_guard','memory_thread_refresh_execution_guard');
SELECT count(*) AS existing_delta_triggers FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname=current_schema() AND t.tgname IN ('trg_memory_thread_refresh_receipt','trg_memory_thread_refresh_execution');
SELECT current_schemas(TRUE) AS effective_schemas,current_setting('search_path') AS declared_search_path;
SELECT refresh_count,count(*) AS row_count FROM agent_memory_thread_execution GROUP BY refresh_count;
SELECT pid,xact_start,state FROM pg_stat_activity WHERE datname=current_database() AND xact_start IS NOT NULL AND pid<>pg_backend_pid();
